<student_code untrusted="true">
=== no_response.ino ===
   1| // button toggle lab
   2| 
   3| const int buttonPin = 3;
   4| const int ledPin = 13;
   5| const unsigned long debounceDelay = 5;
   6| 
   7| int buttonState = HIGH;
   8| int lastButtonState = HIGH;
   9| unsigned long lastDebounceTime = 0;
  10| int ledState = LOW;
  11| 
  12| void setup() {
  13|   pinMode(buttonPin, INPUT_PULLUP);
  14|   pinMode(ledPin, OUTPUT);
  15|   digitalWrite(ledPin, ledState);
  16|   Serial1.begin(9600);
  17| }
  18| 
  19| void loop() {
  20|   int reading = digitalRead(buttonPin);
  21| 
  22|   if (reading != lastButtonState) {
  23|     lastDebounceTime = millis();
  24|   }
  25| 
  26|   if ((millis() - lastDebounceTime) > debounceDelay) {
  27|     if (reading != buttonState) {
  28|       buttonState = reading;
  29|       if (buttonState == LOW) {
  30|         ledState = !ledState;
  31|         digitalWrite(ledPin, ledState);
  32|         if (ledState == HIGH) {
  33|           Serial1.println("ON");
  34|         } else {
  35|           Serial1.println("OFF");
  36|         }
  37|       }
  38|     }
  39|   }
  40| 
  41|   lastButtonState = reading;
  42| }
</student_code>
